<?php
declare(strict_types=1);
require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../includes/referrer_profile.php';require_once __DIR__.'/../includes/referral_opportunities.php';require_once __DIR__.'/../includes/wallet.php';
$user=require_login('REFERRER');$profile=referrer_profile((int)$user['id']);if(!$profile||(int)$profile['is_profile_completed']!==1)redirect('referrer/profile.php');$wallet=referrer_wallet((int)$user['id']);$search=mb_substr(trim((string)($_GET['search']??'')),0,100);$campaignId=filter_var($_GET['campaign_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;$product=mb_substr(trim((string)($_GET['product']??'')),0,150);$date=trim((string)($_GET['date']??''));$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$parsed||$parsed->format('Y-m-d')!==$date)$date='';$sort=($_GET['sort']??'newest')==='oldest'?'oldest':'newest';$page=max(1,(int)($_GET['page']??1));$perPage=20;$transactions=[];$total=0;
if((int)$wallet['id']>0){$where=['wt.wallet_id=?'];$params=[(int)$wallet['id']];if($search!==''){$where[]='(wt.description LIKE ? OR wt.transaction_type LIKE ? OR o.title LIKE ? OR r.product_name LIKE ?)';foreach(range(1,4)as$_)$params[]='%'.$search.'%';}if($campaignId){$where[]='r.opportunity_id=?';$params[]=$campaignId;}if($product!==''){$where[]='r.product_name=?';$params[]=$product;}if($date!==''){$where[]='wt.created_at>=? AND wt.created_at<DATE_ADD(?,INTERVAL 1 DAY)';$params[]=$date.' 00:00:00';$params[]=$date;}$whereSql=implode(' AND ',$where);$count=db()->prepare("SELECT COUNT(*) FROM wallet_transactions wt LEFT JOIN customer_referrals r ON r.id=wt.referral_id LEFT JOIN referral_opportunities o ON o.id=r.opportunity_id WHERE {$whereSql}");$count->execute($params);$total=(int)$count->fetchColumn();$page=min($page,max(1,(int)ceil($total/$perPage)));$stmt=db()->prepare("SELECT wt.*,r.product_name,r.sale_amount,r.commission_percentage,r.calculated_commission,o.title AS opportunity_title FROM wallet_transactions wt LEFT JOIN customer_referrals r ON r.id=wt.referral_id LEFT JOIN referral_opportunities o ON o.id=r.opportunity_id WHERE {$whereSql} ORDER BY wt.created_at ".($sort==='oldest'?'ASC':'DESC').",wt.id ".($sort==='oldest'?'ASC':'DESC')." LIMIT {$perPage} OFFSET ".(($page-1)*$perPage));$stmt->execute($params);$transactions=$stmt->fetchAll();}
$campaigns=db()->prepare('SELECT DISTINCT o.id,o.title FROM customer_referrals r JOIN referral_opportunities o ON o.id=r.opportunity_id JOIN wallet_transactions wt ON wt.referral_id=r.id WHERE wt.wallet_id=? ORDER BY o.title');$campaigns->execute([(int)$wallet['id']]);$products=db()->prepare("SELECT DISTINCT r.product_name FROM wallet_transactions wt JOIN customer_referrals r ON r.id=wt.referral_id WHERE wt.wallet_id=? AND r.product_name IS NOT NULL ORDER BY r.product_name");$products->execute([(int)$wallet['id']]);$query=static function(array $changes=[])use($search,$campaignId,$product,$date,$sort){return http_build_query(array_filter(array_merge(['search'=>$search,'campaign_id'=>$campaignId,'product'=>$product,'date'=>$date,'sort'=>$sort],$changes),static fn($v)=>$v!==''&&$v!==null));};$pageTitle='Transactions | '.APP_NAME;require_once __DIR__.'/../includes/header.php';
?><main class="opportunity-page"><div class="container py-5"><div class="opportunity-hero"><div><span class="eyebrow"><i class="bi bi-receipt"></i> Wallet ledger</span><h1>Transaction history</h1><p>Search and filter every wallet movement.</p></div><a class="btn btn-light border" href="<?=e(url('referrer/wallet.php'))?>">Back to wallet</a></div><section class="opportunity-list-card mt-4"><form class="row g-3 filter-panel" method="get"><div class="col-lg-4"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Search transaction or campaign" data-instant-search></div><div class="col-sm-6 col-lg-2"><select class="form-select" name="campaign_id"><option value="">All campaigns</option><?php foreach($campaigns->fetchAll()as$c):?><option value="<?= (int)$c['id']?>" <?=$campaignId===(int)$c['id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach;?></select></div><div class="col-sm-6 col-lg-2"><select class="form-select" name="product"><option value="">All products</option><?php foreach($products->fetchAll(PDO::FETCH_COLUMN)as$p):?><option <?=$product===$p?'selected':''?>><?=e($p)?></option><?php endforeach;?></select></div><div class="col-sm-4 col-lg-2"><input class="form-control" type="date" name="date" value="<?=e($date)?>"></div><div class="col-sm-4 col-lg-2"><select class="form-select" name="sort"><option value="newest" <?=$sort==='newest'?'selected':''?>>Newest</option><option value="oldest" <?=$sort==='oldest'?'selected':''?>>Oldest</option></select></div><div class="col-12 d-flex gap-2 justify-content-end"><button class="btn btn-outline-primary">Apply filters</button><a class="btn btn-light border" href="<?=e(url('referrer/transactions.php'))?>">Clear filters</a></div></form><?php if(!$transactions):?><div class="empty-state"><span><i class="bi bi-receipt"></i></span><h3>No transactions found</h3><p>Try clearing or adjusting the filters.</p></div><?php else:?><div class="table-responsive"><table class="table opportunity-table align-middle"><thead><tr><th>Date</th><th>Campaign</th><th>Product</th><th>Sale Amount</th><th>Commission %</th><th>Commission Amount</th><th>Type</th><th>Balance After</th></tr></thead><tbody><?php foreach($transactions as$t):?><tr><td><?=e(date('d M Y, h:i A',strtotime($t['created_at'])))?></td><td><?=e($t['opportunity_title']?:'—')?></td><td><?=e($t['product_name']?:'—')?></td><td><?=$t['sale_amount']!==null?e(opportunity_money($t['sale_amount'])):'—'?></td><td><?=$t['commission_percentage']!==null?e($t['commission_percentage']).'%':'—'?></td><td><?=$t['calculated_commission']!==null?e(opportunity_money($t['calculated_commission'])):'—'?></td><td><span class="role-badge"><?=e($t['transaction_type'])?></span></td><td><?=e(opportunity_money($t['balance_after']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($total>$perPage):?><nav class="mt-3"><ul class="pagination justify-content-end mb-0"><?php for($p=1;$p<=ceil($total/$perPage);$p++):?><li class="page-item <?=$p===$page?'active':''?>"><a class="page-link" href="<?=e(url('referrer/transactions.php?'.$query(['page'=>$p])))?>"><?=$p?></a></li><?php endfor;?></ul></nav><?php endif;?></section></div></main><?php require_once __DIR__.'/../includes/footer.php';?>
